corrected_code:
const express = require('express');
const { VapidAuditLog, Project } = require('../models');
const { requireAuth } = require('../auth');

const app = express();

app.get('/api/vapid-keys/:keyId/audit-history', requireAuth, async (req, res) => {
  const { keyId } = req.params;

  // Verify that the key belongs to a project the user has access to
  const project = await Project.findOne({
    where: {
      vapidKeyId: keyId,
      organizationId: req.user.organizationId
    }
  });

  if (!project) {
    return res.status(403).json({ error: 'Access denied: VAPID key does not belong to your organization' });
  }

  const history = await VapidAuditLog.findAll({
    where: { keyId },
    attributes: ['id', 'keyId', 'rotatedAt', 'fingerprint']
  });

  res.json({ keyId, history });
});

app.listen(8105);
